def startup_fields(body):
    """Admit only ordinary version3 UTF-8 sessions with a closed startup parameter set."""
    if body[:4] != integer(196608) or not body.endswith(b'\0'):
        raise ProtocolError('startup_protocol')
    fields = body[4:-1].split(b'\0')
    if fields[-1:] == [b'']:
        fields.pop()
    if len(fields) % 2:
        raise ProtocolError('startup_fields')
    result = {}
    for key, value in zip(fields[::2], fields[1::2]):
        key, value = key.decode('utf-8'), value.decode('utf-8')
        if key in result or key not in {'user', 'database', 'application_name', 'client_encoding', 'options'}:
            raise ProtocolError('startup_parameter')
        result[key] = value
    if not result.get('user') or not result.get('database'):
        raise ProtocolError('startup_identity')
    if result.get('client_encoding', 'UTF8').replace('-', '').upper() != 'UTF8' or result.get('options', ''):
        raise ProtocolError('startup_lexical_mode')
    return result

async def frontend(self):
    """Admit exact SQL before forwarding Q/P; validate all remaining protocol transitions."""
    while True:
        kind, body = await read_frame(self.reader)
        if not self.authenticated:
            if kind != b'p' or len(body) > 65536:
                raise ProtocolError('authentication_phase')
            self.server.record(self.tag, 'auth')
        else:
            await asyncio.wait_for(self.ready_event.wait(), 15)
            if kind in (b'Q', b'P'):
                sql = self.state.sql_request(kind, body)
                decision = await self.server.admit(self.tag, sql)
                self.state.accept_sql(kind, body, sql, decision)
            else:
                self.state.control(kind, body)
            self.server.record(self.tag, kind.decode('ascii'))
        await send(self.backend_writer, packet(kind, body))
        if kind == b'X':
            return

async def backend(self):
    """Enforce the parser's lexical assumptions and COPY phase before exposing backend replies."""
    while True:
        kind, body = await read_frame(self.backend_reader)
        if kind == b'R':
            if len(body) < 4:
                raise ProtocolError('authentication_response')
            method = struct.unpack('!I', body[:4])[0]
            if method == 0:
                self.authenticated = True
            elif method not in (10, 11, 12):
                raise ProtocolError('unsupported_authentication')
        elif kind == b'S':
            self.parameter_status(body)
        elif kind == b'K':
            if len(body) != 8:
                raise ProtocolError('backend_key')
            self.cancel_key = body
            self.server.cancel_keys.add(body)
        elif kind == b'Z':
            if self.lexical != {'client_encoding': 'UTF8', 'standard_conforming_strings': 'on'}:
                raise ProtocolError('unconfirmed_lexical_mode')
            self.state.ready(body)
            self.ready_event.set()
        elif kind == b'G':
            self.state.copy_in = True
        elif kind == b'W':
            raise ProtocolError('copy_both_unsupported')
        await send(self.writer, packet(kind, body))

async def close(self):
    """Reap the owned transport and remove ephemeral cancellation authority."""
    if self.cancel_key is not None:
        self.server.cancel_keys.discard(self.cancel_key)
    for writer in (self.backend_writer, self.writer):
        if writer is not None:
            writer.close()
            try:
                await asyncio.wait_for(writer.wait_closed(), 2)
            except (OSError, asyncio.TimeoutError):
                pass

async def admit(self, tag, sql):
    """Serialize bounded parser work and distinguish SQL rejection from protocol failure."""
    try:
        await asyncio.wait_for(self.parser_slots.acquire(), FRAME_SECONDS)
        try:
            if isinstance(self.gate, ParserGate):
                cancelled = threading.Event()
                work = asyncio.get_running_loop().run_in_executor(
                    None, lambda:self.gate.validate(sql, cancel=cancelled))
                try:
                    decision = await asyncio.shield(work)
                except asyncio.CancelledError:
                    cancelled.set()
                    # Keep the outer slot until the thread owns no child/fd reservation.
                    while not work.done():
                        try:
                            await asyncio.shield(work)
                        except asyncio.CancelledError:
                            # Repeated cancellation cannot release ownership early.
                            cancelled.set()
                        except Exception:
                            break
                    if not work.cancelled():
                        work.exception()  # Consume an expected denial after cancellation.
                    raise
            else:
                decision = await asyncio.to_thread(self.gate.validate, sql)
        finally:
            self.parser_slots.release()
        self.record(tag, 'accepted')
        return decision
    except Exception as error:
        self.record(tag, 'rejected')
        if isinstance(error, SQLGuardError):
            category = error.category
            if category in {'policyDenied','parserFailure','infrastructureFailure'}:
                self.record(tag, 'parser_category_' + category)
        reason = str(error) if isinstance(error, SQLGuardError) else ''
        code = reason.replace(' ', '_') if reason in GATE_REASONS else 'unexpected_failure'
        self.record(tag, 'parser_reason_' + code)
        raise ProtocolError('parser_denied') from None

def validate_dsn(dsn, admin=False, allow_temporary=False, client='allow-app'):
    """Validate every explicit endpoint and force the parser's UTF-8 startup mode."""
    reject_environment_routes()
    from psycopg.conninfo import conninfo_to_dict, make_conninfo
    if not isinstance(dsn,str):
        raise ConnectionPolicyError('database_dsn_required')
    try:
        fields = conninfo_to_dict(dsn)
    except Exception as exc:
        raise ConnectionPolicyError('invalid_database_dsn') from exc
    if set(fields)-ALLOWED_KEYS or fields.get('host') != str(PROXY_DIRECTORY) or fields.get('port') != PORT:
        raise ConnectionPolicyError('owned_proxy_endpoint_required')
    if fields.get('user') != ('allow_admin' if admin else 'allow_app'):
        raise ConnectionPolicyError('unexpected_database_role')
    database = fields.get('dbname')
    temporary = isinstance(database,str) and re.fullmatch(r'allow_(?:recovery|sql_test)_[0-9a-f]{32}',database)
    if database not in ('allow_retrieval','postgres') and not (allow_temporary and temporary):
        raise ConnectionPolicyError('database_not_registered')
    if not admin and database == 'postgres':
        raise ConnectionPolicyError('application_database_required')
    if fields.get('sslmode','disable')!='disable' or fields.get('gssencmode','disable')!='disable':
        raise ConnectionPolicyError('alternate_database_transport_forbidden')
    if fields.get('client_encoding','UTF8').upper().replace('-','') != 'UTF8' or fields.get('options',''):
        raise ConnectionPolicyError('unsafe_database_startup_mode')
    if client not in CLIENT_TAGS:
        raise ConnectionPolicyError('invalid_client_tag')
    fields.update(client_encoding='UTF8',options='',sslmode='disable',gssencmode='disable',
                  application_name=client,connect_timeout='5')
    return make_conninfo(**fields)


def configured_dsn(admin=False, client='allow-app'):
    """Return the canonical authenticated proxy DSN; no environment fallback exists."""
    value = configuration()['admin_dsn' if admin else 'app_dsn']
    return validate_dsn(value,admin=admin,client=client)


def database_dsn(dsn, database, admin=False, client='allow-recovery'):
    """Change only an explicitly registered recovery/test database, retaining the proxy."""
    from psycopg.conninfo import make_conninfo
    base = validate_dsn(dsn,admin=admin,client=client)
    return validate_dsn(make_conninfo(base,dbname=database),admin=admin,allow_temporary=True,client=client)


def connect(dsn=None, admin=False, allow_temporary=False, client='allow-app', **kwargs):
    """Open a connection only after endpoint validation and safe startup normalization."""
    import psycopg
    allowed = {'autocommit','row_factory'}
    if set(kwargs)-allowed:
        raise ConnectionPolicyError('connection_override_forbidden')
    normalized = validate_dsn(dsn or configured_dsn(admin,client),admin,allow_temporary,client)
    # Psycopg's automatic cache emits SQL DEALLOCATE after DDL/rollback.
    # Keep normal parameter Bind frames, but never create that opaque SQL path.
    return psycopg.connect(normalized,prepare_threshold=None,**kwargs)

