def dispatch(frame):
    """Validate closed internal frame before loading durable server-owned scope."""
    wire.fields(frame, {'protocol','requestId','operation','args'})
    if type(frame['protocol']) is not int or frame['protocol'] != 1:
        raise ValueError('invalid_protocol')
    if str(uuid.UUID(frame['requestId'])) != frame['requestId']:
        raise ValueError('invalid_nonce')
    operation,args = frame['operation'],frame['args']
    if operation not in SHAPES:
        raise ValueError('unsupported_operation')
    wire.fields(args, SHAPES[operation])
    store = Store()
    if operation in ('admit','recover','recoverUnstarted'):
        if args['ownerPid'] != os.getppid():
            raise ValueError('owner_must_be_supervisor')
        if operation == 'recoverUnstarted':
            return store.recover_unstarted(args)
        return store.admit(args) if operation == 'admit' else store.recover(args)
    operations = {'init':lambda:store.initialize(args['policyVersion']),
                  'list':store.listing, 'read':lambda:store.read(args),
                  'receipt':lambda:store.receipt(args), 'ownedIds':lambda:store.owned_ids(args),
                  'validationContext':lambda:store.validation_context(args),
                  'finalize':lambda:store.finalize(args),
                  'policy':lambda:store.policy(args['expectedPolicyVersion'],args['policyVersion'])}
    return operations[operation]()

def _history_inventory(self, connection, document, wanted):
    """Resolve requested definition kinds from the entire supplied snapshot.

    Empty requests avoid a scan; otherwise every artifact is decoded and
    checked so a later kind collision or malformed artifact cannot be hidden.
    """
    result = {}
    if wanted:
        rows = connection.execute('SELECT content FROM documents.artifact WHERE document_id=%s',(document,))
        for row in rows:
            artifact = wire.decode(bytes(row['content']),wire.MAX_RESPONSE)
            wire.fields(artifact, wire.ARTIFACT_FIELDS)
            self.collect_ids(artifact['module'],wanted,result)
    return result

def validation_context(self, args):
    """Read one exact base and its requested history inventory atomically.

    Missing scoped data is a request failure. Corrupt stored content or read
    transport failures are unavailable, never an uncertain mutation outcome.
    No context is returned until the read-only transaction has closed.
    """
    document, revision, wanted = self._context_arguments(args)
    try:
        with self._validation_snapshot() as connection:
            snapshot = self._read(connection,document,revision)
            wire.fields(snapshot['artifact'], wire.ARTIFACT_FIELDS)
            result = {'documentId':document,'baseRevision':revision,
                      'headObserved':snapshot['headRevision'],'artifact':snapshot['artifact'],
                      'ownedIdInventory':self._history_inventory(connection,document,wanted)}
    except (ValueError, TypeError, KeyError, UnicodeError, RecursionError) as failure:
        if isinstance(failure,ValueError) and str(failure) in {'document_not_found','revision_not_found'}:
            raise
        raise RuntimeError('validation_context_unavailable') from failure
    except (KnownRollback, UncertainCommit) as failure:
        raise RuntimeError('validation_context_unavailable') from failure

byte[] validate(String document, byte[] bytes) throws IOException, InterruptedException {
    JsonNode request = DocumentJson.request(bytes);
    DocumentJson.fields(request, "draftId", "draftEpoch", "baseRevision", "candidate");
    if (!request.path("draftId").isTextual()) throw new IllegalArgumentException("Invalid draft ID");
    UUID.fromString(request.path("draftId").textValue());
    DocumentJson.revision(request, "draftEpoch");
    long base = DocumentJson.revision(request, "baseRevision");
    runtime.requireReady();
    WorkerCapacity.acquire();
    try {
        JsonNode candidate = request.path("candidate");
        DocumentValidationContext context = DocumentValidationContext.read(gateway, document, base,
                candidate.path("module"));
        DocumentWorker worker = new DocumentWorker();
        if (!worker.identity().equals(runtime.dependency())) throw new IOException("Validator build changed");
        JsonNode outcome = worker.validate(candidate, context.artifact(), context.inventory(), runtime.policy());
        return validationReply(request, bytes, outcome);
    } finally {
        WorkerCapacity.release();
    }
}

JsonNode request(String operation, JsonNode arguments) throws IOException, InterruptedException {
    String nonce = UUID.randomUUID().toString();
    ObjectNode frame = com.fasterxml.jackson.databind.node.JsonNodeFactory.instance.objectNode();
    frame.put("protocol", 1).put("requestId", nonce).put("operation", operation);
    frame.set("args", arguments.deepCopy());
    byte[] input = JsonWire.encode(frame);
    if (input.length >= 3145728) throw new IOException("Persistence frame exceeds limit");
    byte[] output = FrameProcess.exchange(launch(), input, 1572865, 20000);
    JsonNode result = DocumentJson.decode(output);
    DocumentJson.fields(result, "protocol", "requestId", "status", "data");
    if (!result.path("protocol").isInt() || result.path("protocol").intValue() != 1
            || !nonce.equals(result.path("requestId").asText()) || !result.path("data").isObject()) {
        throw new IOException("Persistence response identity mismatch");
    }
    return result;

static byte[] exchange(Process child, byte[] input, int maximum, long millis)
        throws IOException, InterruptedException {
    JobControl control = new JobControl();
    control.attach(child);
    ExecutorService tasks = Executors.newFixedThreadPool(3);
    Future<byte[]> output = tasks.submit(new BoundedCapture(child.getInputStream(), maximum, control));
    Future<byte[]> error = tasks.submit(new BoundedCapture(child.getErrorStream(), 32768, control));
    Future<Void> writer = tasks.submit(new Writer(child, input));
    try {
        if (!child.waitFor(millis, TimeUnit.MILLISECONDS)) throw new IOException("Child deadline exceeded");
        byte[] bytes = output.get(2, TimeUnit.SECONDS);
        error.get(2, TimeUnit.SECONDS);
        writer.get(2, TimeUnit.SECONDS);
        if (child.exitValue() != 0) throw new IOException("Child did not return a valid result");
        framing(bytes);
        return bytes;
    } catch (ExecutionException | TimeoutException failure) {
        throw new IOException("Child frame unavailable", failure);
    } finally {
        control.stop();
        reap(child);
        tasks.shutdownNow();
    }
}

final class WorkerCapacity {
    private static final Semaphore PERMIT = new Semaphore(1);

    /** Prevents construction of the process-wide admission owner. */
    private WorkerCapacity() {}

    /** Acquires without a validation queue, before spawning or durable admission.
     * @throws RejectedExecutionException another local-principal operation is active
     */
    static void acquire() {
        if (!PERMIT.tryAcquire()) throw new RejectedExecutionException("Worker capacity reached");
    }

    /** Releases only after the owner has reaped every child it started. */
    static void release() {
        PERMIT.release();
    }
}

